export default {
  //   【打字机 / typewriter】 —— 前一个文本元素呈现打字机效果，占位不抖动
  //   参数：speed（字符间隔 ms，10-200），scope（prev-sibling / prev-line / prev-block）
  //   示例：@打字机{speed: 60}(逐字展开),
  //   优化：使用隐藏占位文本 + 绝对定位打字层，杜绝布局抖动
  type: 'echo-chant',
  field: 'typewriter',
  title: '打字机',
  version: 2,

  props: {
    speed: 50,
    scope: 'prev-sibling'
  },

  render (props = {}) {
    return '<span class="ag-echo-placeholder-marker"><span class="ag-echo-anno-at" contenteditable="false">@</span><span class="ag-echo-anno-name ag-rune ag-rune--typewriter" contenteditable="false" data-echo-chant-id="typewriter">打字机</span></span>'
  },

  afterRender (node, props = {}) {
    const $ = window.jQuery
    const $rune = $(node)
    if (!$rune.length) return () => {}

    // 幂等保护
    if ($rune[0].__agTypewriterV2Installed) return () => {}
    $rune[0].__agTypewriterV2Installed = true

    const merged = Object.assign({ speed: 50, scope: 'prev-sibling' }, props || {})
    const speed = Math.max(10, Math.min(200, Number(merged.speed) || 50))
    const scope = String(merged.scope).toLowerCase()

    // ---------- 1. 寻找目标元素 ----------
    let $target
    if (scope === 'prev-line' || scope === 'prev-block') {
      $target = $rune.closest('[data-block-type], .mu-block, p, pre, li, h1, h2, h3, h4, h5, h6, blockquote').first().prev()
    } else {
      $target = $rune.prevAll(':not([data-echo-chant-id])').first()
      if (!$target.length) {
        const $block = $rune.closest('[data-block-type], .mu-block, p, pre, li, h1, h2, h3, h4, h5, h6, blockquote').first()
        $target = $block.prev()
      }
    }
    if (!$target.length) {
      delete $rune[0].__agTypewriterV2Installed
      return () => {}
    }

    // 防止对同一目标重复安装
    if ($target.attr('data-typewriter-active') === 'true') {
      delete $rune[0].__agTypewriterV2Installed
      return () => {}
    }
    $target.attr('data-typewriter-active', 'true')

    // ---------- 2. 保存原始状态 ----------
    const originalHTML = $target.html()
    const originalCSS = {
      display: $target.css('display'),
      position: $target.css('position'),
      width: $target.css('width'),
      height: $target.css('height'),
      overflow: $target.css('overflow'),
      whiteSpace: $target.css('whiteSpace')
    }

    const fullText = $target.text()

    // 固定尺寸 + 变为相对定位容器
    const targetWidth = $target.width()
    const targetHeight = $target.height()
    $target.css({
      display: 'inline-block',
      position: 'relative',
      width: targetWidth + 'px',
      height: targetHeight + 'px',
      overflow: 'hidden',
      whiteSpace: 'normal'
    })

    $target.empty()

    // ---------- 3. 创建隐藏占位 span（保持布局）与 打字层 ----------
    const $placeholder = $('<span class="ag-typewriter-placeholder"></span>')
      .text(fullText)
      .css({
        visibility: 'hidden',
        display: 'inline',
        whiteSpace: 'pre-wrap',
        wordBreak: 'break-word'
      })
    $target.append($placeholder)

    // 打字层容器（绝对定位，覆盖于占位文本之上）
    const $typingWrapper = $('<span class="ag-typewriter-typing-wrapper"></span>')
      .css({
        position: 'absolute',
        top: '0',
        left: '0',
        width: '100%',
        height: '100%',
        overflow: 'hidden',
        pointerEvents: 'none'
      })
    const $typingText = $('<span class="ag-typewriter-typing"></span>')
      .css({
        display: 'inline',
        whiteSpace: 'pre-wrap',
        wordBreak: 'break-word'
      })
    const $cursor = $('<span class="ag-typewriter-cursor">|</span>')
      .css({
        display: 'inline',
        animation: 'ag-blink-cursor 0.8s step-end infinite'
      })

    $typingWrapper.append($typingText).append($cursor)
    $target.append($typingWrapper)

    // ---------- 4. 动态计算速度与随机停顿 ----------
    const lengthFactor = Math.max(0, (30 - fullText.length) / 30)
    const baseInterval = Math.round(speed * (1 + lengthFactor * 1.5))
    const pauseChance = 0.2
    const pauseDurationMin = 150
    const pauseDurationMax = 600

    let currentIndex = 0
    let timer = null

    const showNext = () => {
      if (currentIndex >= fullText.length) {
        $cursor.remove()
        return
      }
      // 更新打字区域文本
      $typingText.text(fullText.substring(0, currentIndex + 1))
      currentIndex++

      let nextDelay = baseInterval
      if (Math.random() < pauseChance) {
        const extra = pauseDurationMin + Math.random() * (pauseDurationMax - pauseDurationMin)
        nextDelay += Math.round(extra)
      }
      if (currentIndex > 0 && currentIndex < fullText.length) {
        const prevChar = fullText[currentIndex - 1]
        if (/[,.!?;:]/.test(prevChar)) {
          nextDelay += Math.round(baseInterval * 1.2)
        }
      }
      timer = setTimeout(showNext, nextDelay)
    }

    timer = setTimeout(showNext, baseInterval)

    $rune.addClass('ag-rune-typewriter-active')

    // ---------- 5. cleanup ----------
    const cleanup = () => {
      clearTimeout(timer)
      $target.html(originalHTML)
      $target.css({
        display: originalCSS.display === 'inline' ? '' : (originalCSS.display || ''),
        position: originalCSS.position === 'static' ? '' : (originalCSS.position || ''),
        width: originalCSS.width === 'auto' ? '' : originalCSS.width,
        height: originalCSS.height === 'auto' ? '' : originalCSS.height,
        overflow: originalCSS.overflow || '',
        whiteSpace: originalCSS.whiteSpace || ''
      })
      $target.removeAttr('data-typewriter-active')
      $rune.removeClass('ag-rune-typewriter-active')
      try { delete $rune[0].__agTypewriterV2Installed } catch (e) {}
    }

    return cleanup
  }
}

export default {
  //   【弹幕 / barrage】 —— 匹配上一个文本元素，呈现B站弹幕飘过的特效，原文本元素保留
  //   影响范围（source）：
  //     - prev-sibling(默认) 同行上一个 inline / element 兄弟节点
  //     - prev-line          上一行 block 节点
  //     - next-line          下一行 block 节点
  //   参数：speed=动画秒数（默认8），randomTop=是否随机垂直位置（默认true），top=固定top值（仅在randomTop为false时生效）
  //   示例：@弹幕{source: "prev-line", speed: 6}(让上一行飘过),
  type: 'echo-chant',
  field: 'barrage',
  title: '弹幕',
  version: 1,

  props: {},

  render (props = {}) {
    return '<span class="ag-echo-placeholder-marker"><span class="ag-echo-anno-at" contenteditable="false">@</span><span class="ag-echo-anno-name ag-rune ag-rune--barrage" contenteditable="false" data-echo-chant-id="barrage">弹幕飘过</span></span>'
  },

  //   【handler】复制上一个文本元素为弹幕，添加CSS关键帧动画从右向左飘过；动画结束后自动移除
  afterRender (node, props = {}) {
    const $rune = $(node)
    if (!$rune.length) return () => {}

    const mergedProps = Object.assign({
      source: 'prev-sibling',
      speed: 8,
      randomTop: true,
      top: '50px'
    }, props || {})

    const source = String(mergedProps.source || 'prev-sibling').toLowerCase()
    const speed = Number(mergedProps.speed) || 8
    const $block = $rune.closest('[data-block-type], .mu-block, p, pre, li, h1, h2, h3, h4, h5, h6, blockquote').first()
    if (!$block.length) return () => {}

    let $src
    if (source === 'prev-line' || source === 'prev-block') {
      $src = $block.prev()
    } else if (source === 'next-line' || source === 'next-block') {
      $src = $block.next()
    } else {
      $src = $rune.prevAll(':not([data-echo-chant-id]):not(mark):not(.ag-rune)').first()
      if (!$src.length) $src = $block
    }
    if (!$src.length) return () => {}

    // 动态注入弹幕滚动关键帧（全局一次）
    if (!document.getElementById('ag-danmaku-style')) {
      const style = document.createElement('style')
      style.id = 'ag-danmaku-style'
      style.textContent = `@keyframes ag-danmaku-scroll {
        0% { transform: translateX(100vw); }
        100% { transform: translateX(-100%); }
      }`
      document.head.appendChild(style)
    }

    const barrageId = 'barrage-' + Math.random().toString(36).substr(2, 9)
    const topValue = mergedProps.randomTop
      ? Math.floor(Math.random() * (window.innerHeight - 100)) + 'px'
      : String(mergedProps.top || '50px')

    const $barrage = $src.clone(true)
      .attr('data-barrage-id', barrageId)
      .attr('contenteditable', 'false')
      .addClass('ag-rune-danmaku-barrage')
      .css({
        position: 'fixed',
        left: '0',
        top: topValue,
        zIndex: 9999,
        whiteSpace: 'nowrap',
        pointerEvents: 'none',
        display: 'inline-block',
        width: 'auto',
        animation: `ag-danmaku-scroll ${speed}s linear forwards`
      })

    $('body').append($barrage)

    // 动画结束后自动清理
    $barrage.on('animationend', function () {
      $(this).remove()
    })

    $rune.addClass('ag-rune-danmaku-active')

    return () => {
      $(`[data-barrage-id="${barrageId}"]`).remove()
      $rune.removeClass('ag-rune-danmaku-active')
    }
  }
}
